import { motion } from 'framer-motion';

import { useAboutTitle } from '../../hooks/useAboutTitle';

export default function AboutTitle() {
  const { aboutTitle, isLoading } = useAboutTitle();

  if (isLoading || !aboutTitle) {
    return null;
  }

  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      className="mb-20 text-center px-4 md:px-8"
    >
      <h1 className="text-4xl md:text-5xl lg:text-6xl font-bold leading-tight text-neutral-dark dark:text-white max-w-[90rem] mx-auto">
        <span className="text-primary dark:text-primary-light inline">
          {aboutTitle.headline_highlight}
        </span>{' '}
        <span className="inline">{aboutTitle.headline}</span>
      </h1>
    </motion.div>
  );
}
