import { supabase } from '../lib/supabase/client';

import { useSupabaseQuery } from './useSupabaseQuery';

interface AboutTitleData {
  headline: string;
  headline_highlight: string;
}

export function useAboutTitle() {
  const {
    data: aboutTitle,
    isLoading,
    error,
    refetch,
  } = useSupabaseQuery(
    async () => {
      const { data, error } = await supabase
        .from('about')
        .select('headline, headline_highlight')
        .single();

      if (error) throw error;
      return data as AboutTitleData | null;
    },
    { initialData: null as AboutTitleData | null }
  );

  return { aboutTitle, isLoading, error, refetch };
}
