import { motion } from 'framer-motion';
import { Linkedin, Podcast } from 'lucide-react';
import { useEffect } from 'react';

import AboutTitle from '../components/About/AboutTitle';
import BioText from '../components/About/BioText';
import SEO from '../components/SEO';
import { useAbout } from '../hooks/useAbout';
import { optimizeImageUrl } from '../utils/imageUrl';

export default function AboutPage() {
  const { about, isLoading, error } = useAbout();

  // Force scroll to top on mount
  useEffect(() => {
    window.scrollTo(0, 0);
  }, []);

  if (isLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center" role="status">
        <div className="text-center">
          <div
            className="w-12 h-12 border-4 border-primary border-t-transparent rounded-full animate-spin mb-4"
            aria-hidden="true"
          />
          <p className="text-lg text-neutral-dark/70 dark:text-white/70">
            Loading about information...
          </p>
        </div>
      </div>
    );
  }

  if (error || !about) {
    return (
      <div className="min-h-screen flex items-center justify-center" role="alert">
        <div className="text-center">
          <h1 className="text-2xl font-bold mb-4 text-neutral-dark dark:text-white">
            Unable to load about page
          </h1>
          <p className="text-lg text-neutral-dark/70 dark:text-white/70">
            {error?.message || 'Please try again later'}
          </p>
        </div>
      </div>
    );
  }

  // Split description text into paragraphs and process links
  const paragraphs = about.description_text?.split(/(?<=\.|\?|!)\s+(?=[A-Z])/) || [];

  // Process text for SEO (strip HTML tags)
  const seoDescription = about.description_text
    ?.replace(/<BioLink[^>]*>/g, '')
    .replace(/<\/BioLink>/g, '')
    .split('.')[0];

  return (
    <div className="min-h-screen pt-24 pb-16 bg-gray-50 dark:bg-neutral-darker">
      <SEO
        title="About | REWI.RE"
        description={seoDescription || ''}
        image={about.image_url}
        path="/about"
        type="website"
      />

      <div className="container mx-auto px-6">
        <AboutTitle />

        <motion.section
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          className="bg-white dark:bg-neutral-dark rounded-2xl shadow-lg overflow-hidden"
        >
          <div className="p-8 md:p-12">
            <div className="flex flex-col lg:flex-row items-center gap-12">
              {/* Profile Image */}
              <motion.div
                initial={{ opacity: 0, scale: 0.5 }}
                animate={{ opacity: 1, scale: 1 }}
                transition={{ duration: 0.5 }}
                className="lg:w-1/3"
              >
                <div className="relative w-72 h-72 mx-auto">
                  <div
                    className="absolute inset-0 bg-primary/20 dark:bg-primary/10 blur-2xl transform rotate-3"
                    aria-hidden="true"
                  />
                  <motion.div
                    whileHover={{ scale: 1.02, rotate: 0 }}
                    className="relative w-full h-full"
                  >
                    <img
                      src={optimizeImageUrl(about.image_url, 576)}
                      alt={`${about.title} profile`}
                      className="w-full h-full object-cover rounded-2xl shadow-xl border-4 border-white dark:border-gray-800 transform -rotate-3 transition-transform duration-300"
                      width={288}
                      height={288}
                      decoding="async"
                    />
                  </motion.div>
                </div>
              </motion.div>

              {/* Content */}
              <motion.div
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ duration: 0.5, delay: 0.2 }}
                className="lg:w-2/3"
              >
                <div className="prose prose-lg dark:prose-invert mb-8">
                  {paragraphs.map((paragraph: string, index: number) => (
                    <BioText
                      key={index}
                      text={paragraph.trim()}
                      className="text-lg md:text-xl text-neutral-dark/80 dark:text-white/80 leading-relaxed"
                    />
                  ))}
                </div>

                {/* Social Links */}
                <div className="flex gap-6">
                  <motion.a
                    whileHover={{ scale: 1.1 }}
                    whileTap={{ scale: 0.95 }}
                    href="https://linkedin.com/in/antonc"
                    target="_blank"
                    rel="noopener noreferrer"
                    className="p-4 bg-white dark:bg-gray-800 rounded-full shadow-lg hover:shadow-xl transition-all group"
                    aria-label="LinkedIn Profile"
                  >
                    <Linkedin className="w-6 h-6 text-primary dark:text-primary-light group-hover:text-primary-dark dark:group-hover:text-primary transition-colors" />
                  </motion.a>
                  <motion.a
                    whileHover={{ scale: 1.1 }}
                    whileTap={{ scale: 0.95 }}
                    href="https://open.spotify.com/episode/2MMArHql7kXsftBt57Z4L5"
                    target="_blank"
                    rel="noopener noreferrer"
                    className="p-4 bg-white dark:bg-gray-800 rounded-full shadow-lg hover:shadow-xl transition-all group"
                    aria-label="Listen to Podcast Episode"
                  >
                    <Podcast className="w-6 h-6 text-primary dark:text-primary-light group-hover:text-primary-dark dark:group-hover:text-primary transition-colors" />
                  </motion.a>
                </div>
              </motion.div>
            </div>
          </div>
        </motion.section>
      </div>
    </div>
  );
}
